class Order {
  #id; #limit;
  #lines = [];
  #totalCents = 0;
  constructor(id, creditLimitCents) { this.#id = id; this.#limit = creditLimitCents; }
  addLine(line) {
    if (this.#totalCents + line.amountCents > this.#limit) throw new CreditLimitExceeded();
    this.#lines.push(line);
    this.#totalCents += line.amountCents;
  }
  get lines() { return Object.freeze([...this.#lines]); }   // never the live array
}
